// This file is not generated by Speakeasy. It lets a string flag carry JSON
// when the field it fills cannot hold text.
//
// The generated metadata declares some flags as plain strings although their
// fields are objects or nullable strings. Every one found is an expanded union
// variant field:
//
//	vf test turn create         --body-param.agent.payload               an object
//	vf integration connect      --body-param.<provider>.credentials      objects, 7 flags
//	vf evaluation create        --body-param.<type>.description          nullable strings, 3 flags
//
// setFieldByPath cannot store text in those fields, so each of them failed
// with "cannot convert string to ..." whatever value it was given. Such a flag
// now takes its value the way a JSON flag does, through buildJSONField: JSON
// for an object, and plain text or null for a nullable string. A flag whose
// field holds text is unchanged.
//
// One difference from a JSON flag is kept: buildJSONField reads an empty value
// as not given, while a string flag set to '' on purpose means empty text. So
// a nullable string given '' is sent as "", not left out.

package flagutil

import (
	"fmt"
	"reflect"
	"strings"

	"github.com/spf13/cobra"

	"github.com/voiceflow/cli/internal/sdk/sdkinternal/utils"
)

// fieldTypeAt returns the type of the field at path in t, without allocating
// anything. ok is false when the path does not resolve.
func fieldTypeAt(t reflect.Type, path string) (reflect.Type, bool) {
	for _, name := range strings.Split(path, ".") {
		for t.Kind() == reflect.Ptr {
			t = t.Elem()
		}
		if t.Kind() != reflect.Struct {
			return nil, false
		}
		field, ok := t.FieldByName(name)
		if !ok {
			return nil, false
		}
		t = field.Type
	}
	return t, true
}

// fieldHoldsText reports whether the field at path in t can be set from a
// string flag's text, by the conversion setFieldByPath makes. A path that does
// not resolve reports true, leaving setFieldByPath to describe the problem.
func fieldHoldsText(t reflect.Type, path string) bool {
	field, ok := fieldTypeAt(t, path)
	if !ok {
		return true
	}
	// setFieldByPath allocates the pointer of an optional field and converts
	// into what it points to.
	if field.Kind() == reflect.Ptr {
		field = field.Elem()
	}
	return reflect.TypeOf("").ConvertibleTo(field)
}

// buildNonTextField sets, from a string flag, a field that cannot hold text.
func buildNonTextField(cmd *cobra.Command, v reflect.Value, m FlagMeta, val string) error {
	if val == "" {
		if field, ok := fieldTypeAt(v.Type(), m.FieldPath); ok && targetsStringValue(field) {
			return setEmptyText(v, m)
		}
	}
	return buildJSONField(cmd, v, m)
}

// setEmptyText stores an explicit empty string in a nullable string field.
func setEmptyText(v reflect.Value, m FlagMeta) error {
	field, err := navigateToField(v, m.FieldPath)
	if err != nil {
		return fmt.Errorf("failed to navigate to field for --%s: %w", m.FlagName, err)
	}
	target := reflect.New(field.Type())
	if err := utils.UnmarshalJsonFromString(`""`, target.Interface(), m.Annotations); err != nil {
		return fmt.Errorf("invalid value for --%s: %w", m.FlagName, err)
	}
	field.Set(target.Elem())
	return nil
}
